3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Identity-key helpers shared by the owner mapper and the owner create endpoint: the SHA-256 hex digest
10	 * and the American Soundex code used to build and compare an owner's duplicate-detection identity key.
11	 *
12	 * <p>These live in a plain utility class rather than as default methods on {@link OwnerMapper} so MapStruct
13	 * does not mistake their {@code String -> String} shape for candidate property mapping methods.
14	 */
15	public final class OwnerIdentity {
16	
17	    /**
18	     * Soundex code table for the 26 letters {@code A-Z}, where {@code '0'} marks a letter that is not
19	     * coded (the vowels {@code A E I O U}, plus {@code H W Y}).
20	     */
21	    private static final String SOUNDEX_MAPPING = "01230120022455012623010202";
22	
23	    private OwnerIdentity() {
24	    }
25	
26	    /**
27	     * Computes the lower-case SHA-256 hex digest (64 hex characters) of the given input's UTF-8 bytes.
28	     */
29	    public static String sha256Hex(String input) {
30	        try {
31	            byte[] digest = MessageDigest.getInstance("SHA-256")
32	                .digest(input.getBytes(StandardCharsets.UTF_8));
33	            StringBuilder hex = new StringBuilder();
34	            for (byte b : digest) {
35	                hex.append(String.format("%02x", b));
36	            }
37	            return hex.toString();
38	        } catch (NoSuchAlgorithmException ex) {
39	            throw new IllegalStateException("SHA-256 not available", ex);
40	        }
41	    }
42	
43	    /**
44	     * Computes the American Soundex code of a name: the (upper-cased) first letter followed by three
45	     * digits derived from the remaining consonants. Adjacent letters mapping to the same digit are
46	     * coded once; {@code H} and {@code W} do not break such a run while a vowel does. The result is
47	     * right-padded with {@code '0'} to, or truncated to, four characters. Non-letter characters are
48	     * ignored, and a {@code null} or letterless value yields the empty string.
49	     */
50	    public static String soundex(String value) {
51	        if (value == null) {
52	            return "";
53	        }
54	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
55	        if (letters.isEmpty()) {
56	            return "";
57	        }
58	        StringBuilder code = new StringBuilder();
59	        char first = letters.charAt(0);
60	        code.append(first);
61	        char previous = SOUNDEX_MAPPING.charAt(first - 'A');
62	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
63	            char letter = letters.charAt(i);
64	            char digit = SOUNDEX_MAPPING.charAt(letter - 'A');
65	            if (letter == 'H' || letter == 'W') {
66	                continue;
67	            }
68	            if (digit != '0' && digit != previous) {
69	                code.append(digit);
70	            }
71	            previous = (letter == 'A' || letter == 'E' || letter == 'I'
72	                || letter == 'O' || letter == 'U' || letter == 'Y') ? '0' : digit;
73	        }
74	        while (code.length() < 4) {
75	            code.append('0');
76	        }
77	        return code.toString();
78	    }
79	}
