1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
26	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
28	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
32	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
36	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * Second-level labels of the known disposable email providers (the label immediately before the
41	     * top-level domain of each entry in the create endpoint's disposable-domain blocklist:
42	     * {@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). An email whose domain
43	     * shares one of these labels is considered <em>disposable-adjacent</em> (see
44	     * {@link #isDisposableAdjacentEmail(String)}).
45	     */
46	    java.util.Set<String> DISPOSABLE_EMAIL_LABELS =
47	        java.util.Set.of("mailinator", "tempmail", "guerrillamail");
48	
49	    /**
50	     * Whether the owner is flagged for review. Returns {@code true} when any of the following hold:
51	     * the owner is a possible duplicate ({@link Owner#getPossibleDuplicate()} is {@code true}), the
52	     * owner's email domain is disposable-adjacent (see {@link #isDisposableAdjacentEmail(String)}), or
53	     * the owner's city is over its soft capacity ({@link Owner#getCapacityWarning()} is {@code true},
54	     * i.e. the city had already reached the capacity-warning threshold when the owner was created).
55	     * Otherwise returns {@code false}.
56	     */
57	    default Boolean riskFlag(Owner owner) {
58	        boolean possibleDuplicate = Boolean.TRUE.equals(owner.getPossibleDuplicate());
59	        boolean overSoftCapacity = Boolean.TRUE.equals(owner.getCapacityWarning());
60	        boolean disposableAdjacent = isDisposableAdjacentEmail(owner.getEmail());
61	        return possibleDuplicate || disposableAdjacent || overSoftCapacity;
62	    }
63	
64	    /**
65	     * Whether an email address is <em>disposable-adjacent</em>: its domain's second-level label (the
66	     * label immediately before the top-level domain) matches one of the known disposable providers'
67	     * labels ({@link #DISPOSABLE_EMAIL_LABELS}). This catches domains related to a disposable provider
68	     * without being an exact blocklist entry, such as the same provider under a different top-level
69	     * domain ({@code mailinator.net}) or a subdomain of it ({@code inbox.mailinator.com}). A
70	     * {@code null}, blank, or structurally invalid domain (fewer than two dot-separated labels) is not
71	     * disposable-adjacent.
72	     */
73	    default boolean isDisposableAdjacentEmail(String email) {
74	        if (email == null || email.isBlank()) {
75	            return false;
76	        }
77	        int at = email.lastIndexOf('@');
78	        if (at < 0 || at == email.length() - 1) {
79	            return false;
80	        }
81	        String domain = email.substring(at + 1).toLowerCase(java.util.Locale.ROOT);
82	        String[] labels = domain.split("\\.");
83	        if (labels.length < 2) {
84	            return false;
85	        }
86	        String secondLevel = labels[labels.length - 2];
87	        return DISPOSABLE_EMAIL_LABELS.contains(secondLevel);
88	    }
89	
90	    /**
91	     * Builds the owner's self link, formatted {@code '/api/owners/<id>'} where {@code id} is the
92	     * owner's id. Returns {@code null} when the owner has no id.
93	     */
94	    default String selfLink(Owner owner) {
95	        Integer id = owner.getId();
96	        if (id == null) {
97	            return null;
98	        }
99	        return "/api/owners/" + id;
100	    }
101	
102	    /**
103	     * Derives the owner's age band from the birth date, computed as the owner's age on the
104	     * registration date: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
105	     * {@code SENIOR} at 65 or older. Returns {@code null} when the birth date or registration
106	     * date is absent, so an owner created without a birth date carries no age band.
107	     */
108	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum ageBand(Owner owner) {
109	        java.time.LocalDate birthDate = owner.getBirthDate();
110	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
111	        if (birthDate == null || registrationDate == null) {
112	            return null;
113	        }
114	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
115	        if (age < 18) {
116	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
117	        }
118	        if (age < 65) {
119	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
120	        }
121	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
122	    }
123	
124	    /**
125	     * Derives the owner's duplicate-detection identity key: the lower-case SHA-256 hex digest (64 hex
126	     * characters) of {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}. The telephone and
127	     * email segments are empty when the respective field is absent, and the last-name segment is the
128	     * {@link #soundex(String) Soundex code} of the owner's last name. The telephone and email are already
129	     * stored in their normalized (E.164 / lower-cased) form, so the stored values are used directly. This
130	     * is the single key against which owner duplicates are detected: two owners collide only when their
131	     * whole keys match.
132	     */
133	    default String identityKey(Owner owner) {
134	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
135	        String email = owner.getEmail() == null ? "" : owner.getEmail();
136	        String lastNameCode = OwnerIdentity.soundex(owner.getLastName());
137	        return OwnerIdentity.sha256Hex(telephone + "|" + email + "|" + lastNameCode);
138	    }
139	
140	    /**
141	     * Fixed city-to-region table used to derive an owner's locality.
142	     */
143	    java.util.Map<String, String> CITY_REGION =
144	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
145	
146	    /**
147	     * Inclusive 4-digit postcode range {@code [low, high]} owned by each region: NSW 2000-2099,
148	     * VIC 3000-3099, QLD 4000-4099. Used to resolve an owner's region from the postcode first.
149	     */
150	    java.util.Map<String, int[]> REGION_POSTCODES =
151	        java.util.Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
152	
153	    /**
154	     * Derives the owner's locality, the leading {@code REGION} segment of the owner's member id (the
155	     * unified identity {@code '<REGION><FY><HASH8><CHK>'}, whose region is the run of leading letters
156	     * before the two-digit fiscal year). Only when no member id is present does it fall back to deriving
157	     * the region directly, preferring the postcode's {@link #REGION_POSTCODES} range and then the fixed
158	     * {@link #CITY_REGION} city table. Returns the canonical region string, or {@code "UNKNOWN"} when
159	     * neither source resolves a region.
160	     */
161	    default String locality(Owner owner) {
162	        String region = memberIdRegion(owner);
163	        if (region != null && !region.isEmpty()) {
164	            return region;
165	        }
166	        String postcode = owner.getPostcode();
167	        if (postcode != null) {
168	            try {
169	                int value = Integer.parseInt(postcode.trim());
170	                for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
171	                    int[] range = entry.getValue();
172	                    if (value >= range[0] && value <= range[1]) {
173	                        return entry.getKey();
174	                    }
175	                }
176	            }
177	            catch (NumberFormatException ex) {
178	                // Not a numeric postcode; fall back to the city table below.
179	            }
180	        }
181	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
182	    }
183	
184	    /**
185	     * Fixed region-to-timezone table used to derive an owner's timezone as an IANA name.
186	     */
187	    java.util.Map<String, String> REGION_TIMEZONE =
188	        java.util.Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
189	
190	    /**
191	     * Derives the owner's timezone as an IANA name from the owner's {@link #locality(Owner) locality}
192	     * (region) via the fixed {@link #REGION_TIMEZONE} table: {@code NSW -> Australia/Sydney},
193	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}. Returns {@code null} when
194	     * the region does not resolve to a known timezone (e.g. the locality is {@code "UNKNOWN"}).
195	     */
196	    default String timezone(Owner owner) {
197	        return REGION_TIMEZONE.get(locality(owner));
198	    }
199	
200	    /**
201	     * Known E.164 country calling codes, longest first, used to split a stored E.164 telephone into
202	     * its country code and national digits when formatting {@link #telephoneDisplay(Owner)}.
203	     */
204	    String[] TELEPHONE_COUNTRY_CODES = {"61", "1"};
205	
206	    /**
207	     * Formats the owner's stored E.164 telephone for humans: the country code, a space, then the
208	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
209	     * The country code is recognised from the {@link #TELEPHONE_COUNTRY_CODES} table; when none matches,
210	     * all digits after the {@code '+'} are treated as the national number. Returns {@code null} when the
211	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164 number.
212	     */
213	    default String telephoneDisplay(Owner owner) {
214	        String telephone = owner.getTelephone();
215	        if (telephone == null) {
216	            return null;
217	        }
218	        if (!telephone.startsWith("+")) {
219	            return telephone;
220	        }
221	        String digits = telephone.substring(1);
222	        if (!digits.chars().allMatch(Character::isDigit)) {
223	            return telephone;
224	        }
225	        String countryCode = "";
226	        for (String code : TELEPHONE_COUNTRY_CODES) {
227	            if (digits.startsWith(code) && digits.length() > code.length()) {
228	                countryCode = code;
229	                break;
230	            }
231	        }
232	        String national = digits.substring(countryCode.length());
233	        StringBuilder grouped = new StringBuilder();
234	        for (int i = 0; i < national.length(); i++) {
235	            if (i > 0 && i % 3 == 0) {
236	                grouped.append(' ');
237	            }
238	            grouped.append(national.charAt(i));
239	        }
240	        return "+" + countryCode + " " + grouped;
241	    }
242	
243	    /**
244	     * Derives the owner's preferred contact channel: {@code "EMAIL"} when an email address is
245	     * present (non-blank), otherwise {@code "PHONE"}.
246	     */
247	    default String contactPreference(Owner owner) {
248	        String email = owner.getEmail();
249	        return email != null && !email.isBlank() ? "EMAIL" : "PHONE";
250	    }
251	
252	    /**
253	     * Computes the owner's membership points. Starts at {@code 0} and adds {@code 2} when an email
254	     * is present, {@code 1} when the owner has no namesakes ({@code namesakeCount} is {@code 0}),
255	     * {@code 2} for a household of {@code 3} or more ({@code householdSize}), and {@code 3} when the
256	     * owner's tenure spans at least one elapsed fiscal year (the {@code registrationDate}'s fiscal
257	     * year is earlier than the current date's fiscal year).
258	     */
259	    default Integer membershipPoints(Owner owner) {
260	        Integer namesakeCount = owner.getNamesakeCount();
261	        String email = owner.getEmail();
262	        Integer householdSize = owner.getHouseholdSize();
263	        int points = 0;
264	        if (email != null && !email.isBlank()) {
265	            points += 2;
266	        }
267	        if (namesakeCount != null && namesakeCount == 0) {
268	            points += 1;
269	        }
270	        if (householdSize != null && householdSize >= 3) {
271	            points += 2;
272	        }
273	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
274	        boolean hasTenure = registrationDate != null
275	            && fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate) >= 1;
276	        if (hasTenure) {
277	            points += 3;
278	        }
279	        return points;
280	    }
281	
282	    /**
283	     * Derives the owner's membership level, a number from 1 to 4, from the owner's
284	     * {@link #membershipPoints(Owner) membership points}: level {@code 1} for {@code 0-1} points,
285	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
286	     *
287	     * <p>The derived level is then capped by the owner's {@code membershipLevelCap} when one was
288	     * snapshotted at creation: a new owner's membership level cannot exceed one above the highest
289	     * membership level among their existing household members. When no cap is present (the owner had no
290	     * existing household member) the derived level is returned unchanged.
291	     */
292	    default Integer membershipLevel(Owner owner) {
293	        int points = membershipPoints(owner);
294	        int level;
295	        if (points <= 1) {
296	            level = 1;
297	        } else if (points <= 3) {
298	            level = 2;
299	        } else if (points <= 5) {
300	            level = 3;
301	        } else {
302	            level = 4;
303	        }
304	        Integer cap = owner.getMembershipLevelCap();
305	        if (cap != null && level > cap) {
306	            return cap;
307	        }
308	        return level;
309	    }
310	
311	    /**
312	     * Known regions considered {@code METRO} for the owner's segment: NSW, VIC and QLD.
313	     */
314	    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
315	
316	    /**
317	     * Derives the owner's segment, formatted {@code '<TIER>_<AREA>'}. {@code TIER} is {@code PREMIUM}
318	     * when the owner's {@link #membershipLevel(Owner) membership level} is {@code 3} or more, otherwise
319	     * {@code STANDARD}. {@code AREA} is {@code METRO} when the owner's {@link #locality(Owner) locality}
320	     * is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
321	     */
322	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
323	        Integer level = membershipLevel(owner);
324	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
325	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
326	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.OwnerSegmentEnum
327	            .fromValue(tier + "_" + area);
328	    }
329	
330	    /**
331	     * Derives the owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the two-digit
332	     * fiscal year. The value is read from the {@code FY} segment of the owner's member id (the two
333	     * digits following the leading region of {@code '<REGION><FY><HASH8><CHK>'}), so it references the
334	     * same fiscal year embedded in the member id. Only when no member id is present does it fall back to
335	     * computing the fiscal year from the business-day-adjusted registration date. Returns {@code null}
336	     * when neither a member id nor a registration date is available.
337	     */
338	    default String fiscalYear(Owner owner) {
339	        String fy = memberIdFiscalYear(owner);
340	        if (fy != null) {
341	            return "FY" + fy;
342	        }
343	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
344	        if (registrationDate == null) {
345	            return null;
346	        }
347	        return String.format("FY%02d", fiscalYearValue(registrationDate) % 100);
348	    }
349	
350	    /**
351	     * Extracts the leading {@code REGION} segment from the owner's member id: the run of leading letters
352	     * before the two-digit fiscal year in {@code '<REGION><FY><HASH8><CHK>'}. Returns {@code null} when
353	     * the owner has no member id.
354	     */
355	    default String memberIdRegion(Owner owner) {
356	        String memberId = owner.getMemberId();
357	        if (memberId == null) {
358	            return null;
359	        }
360	        int i = 0;
361	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
362	            i++;
363	        }
364	        return memberId.substring(0, i);
365	    }
366	
367	    /**
368	     * Extracts the two-digit {@code FY} segment from the owner's member id: the two digits immediately
369	     * following the leading region in {@code '<REGION><FY><HASH8><CHK>'}. Returns {@code null} when the
370	     * owner has no member id or the segment is not present.
371	     */
372	    default String memberIdFiscalYear(Owner owner) {
373	        String region = memberIdRegion(owner);
374	        if (region == null) {
375	            return null;
376	        }
377	        String memberId = owner.getMemberId();
378	        if (memberId.length() < region.length() + 2) {
