253	    /**
254	     * Reads the caller-supplied {@code Idempotency-Key} header from the current request, returning
255	     * {@code null} when the header is absent or blank so callers can treat those uniformly as "no key".
256	     *
257	     * @return the trimmed idempotency key, or {@code null} when none was supplied
258	     */
259	    private String idempotencyKey() {
260	        String value = request.getHeader(IDEMPOTENCY_KEY_HEADER);
261	        if (value == null || value.isBlank()) {
262	            return null;
263	        }
264	        return value.strip();
265	    }
